templates.template:
        // Build permalink page (/builds/<family>/<build>/). Rides the style's own
// block chrome; the hero, pills, kind chips and list rows are bespoke.
//
// Colour: every tone is declared as a light value first and then overridden
// with light-dark() for browsers that support it; XF sets color-scheme on
// :root for both explicit variations and the system setting, so the pair
// follows the visitor's choice. Contrast targets: >= 4.5:1 for text, >= 3:1
// for the chip labels on their tinted backgrounds, in both schemes.
.wbb
{
    --wbb-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    --wbb-muted: #5b6470;
    --wbb-muted: light-dark(#5b6470, #c2c9d2);
    --wbb-accent: #1d5fb4;
    --wbb-accent: light-dark(#1d5fb4, #8fc1ff);
    --wbb-hero-tint: rgba(29, 95, 180, .08);
    --wbb-hero-tint: light-dark(rgba(29, 95, 180, .08), rgba(143, 193, 255, .10));
}
.wbb--release { --wbb-hero-tint: rgba(16, 140, 88, .10); --wbb-hero-tint: light-dark(rgba(16, 140, 88, .10), rgba(74, 222, 128, .09)); }
.wbb--preview { --wbb-hero-tint: rgba(109, 79, 194, .10); --wbb-hero-tint: light-dark(rgba(109, 79, 194, .10), rgba(185, 164, 255, .10)); }
.wbb--beta { --wbb-hero-tint: rgba(180, 83, 9, .10); --wbb-hero-tint: light-dark(rgba(180, 83, 9, .10), rgba(251, 191, 36, .10)); }
.wbb--dotnet { --wbb-hero-tint: rgba(124, 58, 237, .08); --wbb-hero-tint: light-dark(rgba(124, 58, 237, .08), rgba(196, 181, 253, .10)); }

.wbb-mono { font-family: var(--wbb-mono); }
.wbb-muted { color: var(--wbb-muted); }
// Inside the blue block headers the muted grey fails contrast; inherit white.
.block-header .wbb-muted { color: inherit; font-weight: 400; }
.wbb-fineprint
{
    margin: 10px 0 0;
    font-size: @xf-fontSizeSmallest;
    color: var(--wbb-muted);
}

.wbb-prevnext
{
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin: 0 0 10px;
    font-size: @xf-fontSizeSmaller;

    .wbb-prevnext-link,
    .wbb-prevnext-line
    {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        min-height: 44px;
        padding: 0 6px;
        font-weight: 600;
    }
}

.wbb-hero .block-container
{
    background-image: linear-gradient(135deg, var(--wbb-hero-tint), transparent 60%);
}
.wbb-hero-inner { padding: 22px 22px 18px; }
.wbb-eyebrow
{
    margin: 0;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .08em;
    text-transform: uppercase;
    color: var(--wbb-muted);

    a { color: var(--wbb-accent); }
}
.wbb-buildNumber
{
    margin: 6px 0 2px;
    font-family: var(--wbb-mono);
    font-size: 40px;
    font-weight: 800;
    letter-spacing: -.02em;
    line-height: 1.1;
    color: @xf-textColor;

    @media (max-width: @xf-responsiveMedium) { font-size: 32px; }
}
.wbb-title
{
    margin: 0 0 12px;
    font-size: @xf-fontSizeLarge;
    color: @xf-textColor;
}
.wbb-pills
{
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 0 0 12px;
    padding: 0;
    list-style: none;
}
.wbb-pill
{
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 4px 11px;
    border-radius: 999px;
    font-size: 12.5px;
    font-weight: 600;
    line-height: 1.5;
    background: @xf-contentAltBg;
    color: @xf-textColor;

    &--mono, &--kb { font-family: var(--wbb-mono); }
    &--release { background: #d7f3e6; color: #0b5e3b; background: light-dark(#d7f3e6, rgba(16, 185, 129, .22)); color: light-dark(#0b5e3b, #7ef0c1); }
    &--preview { background: #e6dfff; color: #4b2ea8; background: light-dark(#e6dfff, rgba(139, 92, 246, .24)); color: light-dark(#4b2ea8, #cdbcff); }
    &--beta { background: #fdebd0; color: #8a4a05; background: light-dark(#fdebd0, rgba(245, 158, 11, .22)); color: light-dark(#8a4a05, #ffd08a); }
    &--experimental { background: #dbeafe; color: #1e40af; background: light-dark(#dbeafe, rgba(59, 130, 246, .22)); color: light-dark(#1e40af, #a9c8ff); }
}
.wbb-lineNote
{
    margin: 0 0 12px;
    padding: 8px 12px;
    border-left: 3px solid var(--wbb-accent);
    border-radius: 0 6px 6px 0;
    font-size: @xf-fontSizeSmaller;
    background: @xf-contentAltBg;
    color: @xf-textColor;

    &--preview { border-left-color: #6d4fc2; border-left-color: light-dark(#6d4fc2, #b9a4ff); }
    &--silicon { border-left-color: #1d6fa5; border-left-color: light-dark(#1d6fa5, #7cc4f5); }
    &--eol { border-left-color: #b42323; border-left-color: light-dark(#b42323, #ff8a8a); }
    &--dotnet { border-left-color: #7c3aed; border-left-color: light-dark(#7c3aed, #c4b5fd); }
}
.wbb-actions
{
    display: flex;
    flex-wrap: wrap;
    gap: 8px;

    .wbb-btn { min-height: 44px; }
}

.wbb-grid
{
    display: grid;
    grid-template-columns: minmax(0, 1fr) 320px;
    gap: 0 18px;
    align-items: start;

    @media (max-width: @xf-responsiveWide) { grid-template-columns: minmax(0, 1fr); }
}
.wbb-main, .wbb-side { min-width: 0; }

.wbb-list
{
    margin: 0;
    padding: 0;
    list-style: none;
}
.wbb-item
{
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 2px 10px;
    padding: 10px 0;
    border-bottom: 1px solid @xf-borderColorFaint;

    &:last-child { border-bottom: 0; }

    .wbb-item-title { grid-column: 2; font-weight: 600; }
    .wbb-item-meta { grid-column: 2; font-size: @xf-fontSizeSmallest; color: var(--wbb-muted); }
    .wbb-kind { grid-row: 1 / span 2; align-self: start; margin-top: 2px; }

    &--current .wbb-item-title { color: var(--wbb-accent); }

    .wbb-item-body { grid-column: 2; font-size: @xf-fontSizeSmaller; line-height: 1.45; }
    &--ms .wbb-kind { grid-row: 1 / span 4; }
}
.wbb-list--compact .wbb-item
{
    grid-template-columns: minmax(0, 1fr);
    padding: 0;

    // Whole row is the target (>= 44px tall) so the compact lists pass the
    // touch-target check without growing the sidebar.
    .wbb-item-title
    {
        display: block;
        grid-column: 1;
        padding: 9px 0 0;
        min-height: 24px;
    }
    .wbb-item-meta { grid-column: 1; padding-bottom: 9px; }
    .wbb-item-title:only-child { padding: 12px 0; }
}
.wbb-kind
{
    display: inline-block;
    min-width: 62px;
    padding: 2px 7px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 700;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: .04em;
    background: @xf-contentAltBg;
    color: var(--wbb-muted);

    &--issue { background: #fde2e2; color: #9f1c1c; background: light-dark(#fde2e2, rgba(239, 68, 68, .22)); color: light-dark(#9f1c1c, #ffb4b4); }
    &--fix { background: #d7f3e6; color: #0b5e3b; background: light-dark(#d7f3e6, rgba(16, 185, 129, .22)); color: light-dark(#0b5e3b, #7ef0c1); }
    &--coverage { background: #dbeafe; color: #1e40af; background: light-dark(#dbeafe, rgba(59, 130, 246, .22)); color: light-dark(#1e40af, #a9c8ff); }
    &--howto { background: #fdebd0; color: #8a4a05; background: light-dark(#fdebd0, rgba(245, 158, 11, .22)); color: light-dark(#8a4a05, #ffd08a); }
}
.wbb-more
{
    display: flex;
    flex-wrap: wrap;
    gap: 6px 14px;
    margin: 10px 0 0;
    font-size: @xf-fontSizeSmaller;

    a { display: inline-flex; align-items: center; min-height: 32px; }
}
.wbb-textBtn { gap: 6px; font-weight: 600; }

.wbb-facts
{
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    gap: 7px 12px;
    margin: 0;
    font-size: @xf-fontSizeSmaller;

    dt { color: var(--wbb-muted); white-space: nowrap; }
    dd { margin: 0; overflow-wrap: anywhere; }
}
.wbb-uuid { font-size: @xf-fontSizeSmallest; }

.wbb-summary p { margin: 0 0 .75em; }
.wbb-summary p:last-of-type { margin-bottom: 0; }

@media print
{
    .wbb-actions, .wbb-prevnext, .wbb-side .block:last-child { display: none; }
    .wbb-grid { grid-template-columns: minmax(0, 1fr); }
}

        // "Update details" thread sidebar card.
//
// Rides the shared .wf-sideCard chrome from style 40's extra.less section 15,
// but every colour is declared as a plain light value first and then repeated
// through light-dark() (same approach as windowsbuilds_build.less), so the card
// still reads correctly in style 17, which carries no wf-sideCard rules at all.
.wbbUpdate
{
    --wbbu-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
    --wbbu-muted: #5b6470;
    --wbbu-muted: light-dark(#5b6470, #b3bac4);
    --wbbu-accent: #1d5fb4;
    --wbbu-accent: light-dark(#1d5fb4, #8fc1ff);
    --wbbu-line: rgba(0, 0, 0, .10);
    --wbbu-line: light-dark(rgba(0, 0, 0, .10), rgba(255, 255, 255, .14));
    --wbbu-tint: rgba(29, 95, 180, .06);
    --wbbu-tint: light-dark(rgba(29, 95, 180, .06), rgba(143, 193, 255, .08));
}

.wbbUpdate .wf-sideCard-head { display: flex; align-items: center; gap: 8px; }

.wbbUpdate-build
{
    display: block;
    padding: 10px 12px;
    margin-bottom: 12px;
    border: 1px solid var(--wbbu-line);
    border-radius: 6px;
    background: var(--wbbu-tint);
    text-decoration: none;
}
.wbbUpdate-build:hover { border-color: var(--wbbu-accent); }
// No build page for this number (release-health knows it, the UUP feed does not).
.wbbUpdate-build--plain { cursor: default; }
.wbbUpdate-build--plain .wbbUpdate-buildNumber { color: inherit; }
.wbbUpdate-alsoPlain { font-family: var(--wbbu-mono); }
.wbbUpdate-buildNumber
{
    display: block;
    font-family: var(--wbbu-mono);
    font-size: 17px;
    font-weight: 600;
    line-height: 1.25;
    color: var(--wbbu-accent);
}
.wbbUpdate-buildFamily
{
    display: block;
    margin-top: 2px;
    font-size: 12px;
    color: var(--wbbu-muted);
}

.wbbUpdate-facts { margin: 0; }
.wbbUpdate-fact
{
    display: flex;
    justify-content: space-between;
    gap: 12px;
    padding: 6px 0;
    border-top: 1px solid var(--wbbu-line);
    font-size: 13px;
}
.wbbUpdate-fact:first-child { border-top: 0; padding-top: 0; }
.wbbUpdate-fact dt { flex: 0 0 auto; color: var(--wbbu-muted); font-weight: 400; }
.wbbUpdate-fact dd { flex: 1 1 auto; margin: 0; text-align: right; }

.wbbUpdate-alsoBlock,
.wbbUpdate-cveBlock { border-top: 1px solid var(--wbbu-line); }
.wbbUpdate-alsoBlock h3,
.wbbUpdate-cveBlock h3
{
    margin: 0 0 6px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: .06em;
    text-transform: uppercase;
    color: var(--wbbu-muted);
}
.wbbUpdate-also { margin: 0; padding: 0; list-style: none; font-size: 13px; }
.wbbUpdate-also li { padding: 3px 0; }
.wbbUpdate-also a { font-family: var(--wbbu-mono); }
.wbbUpdate-alsoMeta { margin-left: 6px; font-size: 12px; color: var(--wbbu-muted); }

.wbbUpdate-cves { display: flex; flex-wrap: wrap; gap: 6px; margin: 0; padding: 0; list-style: none; }
.wbbUpdate-cves a
{
    display: inline-block;
    padding: 2px 7px;
    border: 1px solid var(--wbbu-line);
    border-radius: 999px;
    font-family: var(--wbbu-mono);
    font-size: 12px;
    line-height: 1.5;
    text-decoration: none;
}
.wbbUpdate-cves a:hover { border-color: var(--wbbu-accent); }
.wbbUpdate-more { margin: 6px 0 0; font-size: 12px; color: var(--wbbu-muted); }
.wbbUpdate-freshness
{
    border-top: 1px solid var(--wbbu-line);
    font-size: 12px;
    color: var(--wbbu-muted);
}

// Minimum touch target for the card's own links on coarse pointers.
@media (pointer: coarse)
{
    .wbbUpdate-fact dd a,
    .wbbUpdate-also a,
    .wbbUpdate-cves a { display: inline-block; min-height: 24px; }
}
